def fires(b):
    if b.last_col is None or b.last_row == 0:
        return False
    return b.grid[b.last_row - 1][b.last_col] == 1 and b.ply <= 24

def level(b):
    return 5 if fires(b) else 0

def blocked(b):
    if b.last_col is None:
        return 0
    r, c = b.last_row, b.last_col
    best = 0
    for s in range(max(0, c - 3), min(3, c) + 1):
        cells = [b.grid[r][s + k] for k in range(4) if s + k != c]
        if 2 in cells:
            continue
        best = max(best, cells.count(1))
    return best

def fires(b):
    return blocked(b) >= 2

def level(b):
    k = blocked(b)
    return 0 if k < 2 else (5 if k == 2 else 8)

def alive(g, r, c):
    # number of horizontal 4-windows containing (r,c),(r,c+1) with no opponent stone
    n = 0
    for s in range(max(0, c - 2), min(3, c) + 1):
        if all(g[r][s + k] != 2 for k in range(4)):
            n += 1
    return n

def score(b):
    if b.last_col is None:
        return 0
    lr, lc = b.last_row, b.last_col
    g = [row[:] for row in b.grid]
    best = 0
    for r in range(0, 3):
        for c in range(0, 6):
            if g[r][c] == 1 and g[r][c + 1] == 1 and r == lr and abs(lc - c) <= 3 and lc != c and lc != c + 1:
                g[lr][lc] = 0
                before = alive(g, r, c)
                g[lr][lc] = 2
                after = alive(g, r, c)
                if before > 0 and after == 0:
                    best = max(best, 2 if 1 <= c <= 2 else 1)
    return best

def fires(b):
    return score(b) >= 1

def level(b):
    return [0, 4, 8][score(b)]

def nbr(b):
    if b.last_col is None:
        return 0
    r, c = b.last_row, b.last_col
    n = 0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            rr, cc = r + dr, c + dc
            if (dr or dc) and 0 <= rr < 6 and 0 <= cc < 7 and b.grid[rr][cc] == 1:
                n += 1
    return n

def fires(b):
    return nbr(b) >= 3 and len(b.my_playable_wins) == 0 and b.ply <= 28

def level(b):
    if len(b.my_playable_wins) > 0:
        return 0
    return min(9, 2 * nbr(b))

def fires(b):
    # opponent's last stone lands in a central-left column (1-4), directly on one of my stones,
    # in the opening/middlegame, and I have no immediate win
    if b.last_col is None or b.last_row == 0:
        return False
    if b.last_col < 1 or b.last_col > 4 or b.ply < 5 or b.ply > 24:
        return False
    if len(b.my_playable_wins) > 0:
        return False
    return b.grid[b.last_row - 1][b.last_col] == 1

def level(b):
    if not fires(b):
        return 0
    return 6 if b.last_col in (1, 2) else 4
